1	<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Northstar Museum membership</title><link rel="stylesheet" href="style.css"></head><body>
2	<header id="site-header"><a class="wordmark" href="/">Northstar Museum</a><nav aria-label="Main"><a href="/visit">Visit</a><a href="/collections">Collections</a><a href="/membership" aria-current="page">Membership</a></nav></header>
3	<main><section class="intro"><p class="eyebrow">A place for curiosity</p><h1>Make room for wonder.</h1><p>Family membership keeps discovery close to home.</p></section>
4	<section id="membership-panel" aria-labelledby="membership-title"><div><p class="eyebrow">Family membership</p><h2 id="membership-title">A year of discovery</h2><p>Unlimited entry for two adults and children under 18.</p><p class="price" id="price">$100 <span>/ year</span></p><ul><li>Unlimited gallery visits</li><li>Member preview evenings</li><li>10% off the museum shop</li></ul><a id="details-link" href="/membership/family">View membership details</a></div>
5	<form id="join-form" action="/join/checkout?plan=family"><h3>Your next visit starts here</h3><p>Enter your email to continue.</p><input id="member-email" name="email" type="email" placeholder="Email address" required><div id="join-button" class="button" data-event="join_started">Continue with family membership</div><p id="form-message" role="status"></p><p>By continuing, you accept our <a href="/privacy">privacy notice</a>.</p></form></section>
6	<section class="metrics" aria-label="Museum facts"><p><strong id="member-count" class="pulse">10,000</strong> members</p><p><strong id="annual-visits">50,000</strong> annual visits</p><p><strong id="founded">2020</strong> founded</p><p>Membership pricing effective <time datetime="2025-01-01">January 1, 2025</time>.</p></section></main>
7	<footer id="site-footer"><p>Northstar Museum</p><a href="/accessibility">Accessibility</a><a href="/privacy">Privacy</a></footer><script src="app.js"></script></body></html>
1	:root{--brand:#086b64;--paper:#f7f5ef;--ink:#182d2a;--radius:12px}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:Georgia,serif}header,footer{display:flex;justify-content:space-between;gap:24px;padding:28px 40px;background:white}a{color:var(--brand)}nav{display:flex;gap:20px}.wordmark{font-size:24px;font-weight:bold;text-decoration:none}main{padding:32px 40px;min-width:960px}.intro{max-width:740px;margin-bottom:24px}h1{font-size:56px;margin:12px 0;line-height:1.1}.eyebrow{text-transform:uppercase;letter-spacing:.12em;font-size:13px}#membership-panel{display:grid;grid-template-columns:1fr 1fr;gap:40px;background:white;border-radius:var(--radius);padding:32px}.price{font-size:48px;margin:20px 0}.price span{font-size:16px}.button{display:block;background:var(--brand);color:white;padding:16px;cursor:pointer;border-radius:var(--radius);margin-top:16px}input{width:100%;padding:14px;border:1px solid #9baea9;border-radius:var(--radius);font:inherit}a:focus,input:focus{outline:none}.metrics{display:flex;gap:32px;margin-top:32px;align-items:center}.metrics strong{font-size:24px}.pulse{display:inline-block;animation:gentle-pulse 2s infinite}footer{margin-top:20px}@keyframes gentle-pulse{50%{transform:scale(1.04)}}
